    const yy = 4.2 + i * 0.45;
    const barW = (parseFloat(item.score) / 60) * 3.0;
    s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: yy, w: barW, h: 0.25, fill: { color: item.color }, transparency: 20 });
    s.addText(item.model, { x: 0.7, y: yy - 0.18, w: 2.5, h: 0.2, fontFace: FONT_B, fontSize: 8, color: C.textSecondary, margin: 0 });
    s.addText(item.score, { x: 0.7 + barW + 0.1, y: yy, w: 0.6, h: 0.25, fontFace: FONT_B, fontSize: 10, color: item.color, bold: true, margin: 0, valign: "middle" });
  });

  // Right: VISTA + VisualToolBench
  s.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 1.5, w: 4.4, h: 3.5, fill: { color: C.bgCard }, shadow: mkShadow() });
  s.addText("VISTA (Vision-Language)", {
    x: 5.4, y: 1.6, w: 4.0, h: 0.35,
    fontFace: FONT_H, fontSize: 14, color: C.textPrimary, bold: true, margin: 0,
  });

  const vistaData = [
    { model: "Gemini 2.5 Pro Exp", score: "54.65", color: C.google },
    { model: "GPT-5.4-pro", score: "53.89", color: C.openai },
  ];

  vistaData.forEach((item, i) => {
    const yy = 2.2 + i * 0.9;
    // Large score
    s.addText(item.score, {
      x: 5.5, y: yy, w: 1.5, h: 0.5,
      fontFace: FONT_H, fontSize: 30, color: item.color, bold: true, margin: 0,
    });
    s.addText(item.model, {
      x: 5.5, y: yy + 0.5, w: 2.5, h: 0.25,
      fontFace: FONT_B, fontSize: 11, color: C.textSecondary, margin: 0,
    });
  });

  // VisualToolBench
  s.addShape(pres.shapes.LINE, { x: 5.5, y: 4.0, w: 3.8, h: 0, line: { color: C.gridLine, width: 1 } });

  s.addText("VisualToolBench", {
    x: 5.4, y: 4.15, w: 4.0, h: 0.3,
    fontFace: FONT_H, fontSize: 13, color: C.textPrimary, bold: true, margin: 0,
  });
  s.addText([
    { text: "GPT-5.4 ", options: { bold: true, color: C.openai } },
    { text: "29.17  vs  ", options: { color: C.textSecondary } },
    { text: "Gemini-3.1-pro ", options: { bold: true, color: C.google } },
    { text: "28.97", options: { color: C.textSecondary } },
  ], {
    x: 5.5, y: 4.45, w: 3.8, h: 0.35,
    fontFace: FONT_B, fontSize: 12, margin: 0,
  });
}

// =====================================================================
// SLIDE 6: SAFETY & ALIGNMENT (contrast visualization)
// =====================================================================
{
  const s = pres.addSlide();
  s.background = { color: C.bgLight };

  s.addText("Safety Alignment: Near-Ceiling Honesty, Critically Low Security", {
    x: 0.6, y: 0.3, w: 9, h: 0.6,
    fontFace: FONT_H, fontSize: 26, color: C.textPrimary, bold: true, margin: 0,
  });
  s.addText("Claude dominates safety benchmarks, but Fortress scores reveal persistent gaps across all models", {
    x: 0.6, y: 0.85, w: 9, h: 0.35,
    fontFace: FONT_B, fontSize: 13, color: C.textSecondary, margin: 0,
  });

  // Left panel: MASK high scores (green)
  s.addShape(pres.shapes.RECTANGLE, { x: 0.4, y: 1.5, w: 4.4, h: 2.3, fill: { color: C.bgCard }, shadow: mkShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.4, y: 1.5, w: 4.4, h: 0.07, fill: { color: C.highScore } });

  s.addText("MASK (Honesty)", {
    x: 0.6, y: 1.7, w: 3.0, h: 0.3,
    fontFace: FONT_H, fontSize: 14, color: C.highScore, bold: true, margin: 0,
  });
  s.addText("NEAR CEILING", {
    x: 3.2, y: 1.7, w: 1.4, h: 0.3,
    fontFace: FONT_B, fontSize: 9, color: C.highScore, bold: true, align: "right", margin: 0,
  });

  // MASK bars
  const maskData = [
    { model: "Claude Opus 4.6", score: 96.28, ci: "±0.41" },
    { model: "Claude Sonnet 4", score: 96.13, ci: "±0.57" },
  ];

  maskData.forEach((item, i) => {
    const yy = 2.2 + i * 0.7;
    const barW = (item.score / 100) * 3.6;
    s.addShape(pres.shapes.RECTANGLE, { x: 0.65, y: yy + 0.22, w: barW, h: 0.3, fill: { color: C.highScore }, transparency: 10 + i * 15 });
    s.addText(item.model, { x: 0.65, y: yy, w: 2.5, h: 0.22, fontFace: FONT_B, fontSize: 10, color: C.textSecondary, margin: 0 });
    s.addText(item.score.toFixed(2) + " " + item.ci, { x: 0.65 + barW + 0.1, y: yy + 0.22, w: 1.0, h: 0.3, fontFace: FONT_B, fontSize: 10, color: C.highScore, bold: true, margin: 0, valign: "middle" });
  });

  // Right panel: Fortress low scores (red)
  s.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 1.5, w: 4.4, h: 2.3, fill: { color: C.bgCard }, shadow: mkShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 1.5, w: 4.4, h: 0.07, fill: { color: C.lowScore } });

  s.addText("Fortress (National Security)", {
    x: 5.4, y: 1.7, w: 3.0, h: 0.3,
    fontFace: FONT_H, fontSize: 14, color: C.lowScore, bold: true, margin: 0,
  });
  s.addText("CRITICALLY LOW", {
    x: 8.0, y: 1.7, w: 1.4, h: 0.3,
    fontFace: FONT_B, fontSize: 9, color: C.lowScore, bold: true, align: "right", margin: 0,
  });

  const fortressData = [
    { model: "Top Model", score: 8.24, ci: "±1.93" },
    { model: "Claude Sonnet 4", score: 12.80, ci: "±2.36" },
  ];

  fortressData.forEach((item, i) => {
    const yy = 2.2 + i * 0.7;
    const barW = (item.score / 100) * 3.6;
    s.addShape(pres.shapes.RECTANGLE, { x: 5.45, y: yy + 0.22, w: barW, h: 0.3, fill: { color: C.lowScore }, transparency: 10 + i * 15 });
    s.addText(item.model, { x: 5.45, y: yy, w: 2.5, h: 0.22, fontFace: FONT_B, fontSize: 10, color: C.textSecondary, margin: 0 });
    s.addText(item.score.toFixed(2) + " " + item.ci, { x: 5.45 + barW + 0.15, y: yy + 0.22, w: 1.2, h: 0.3, fontFace: FONT_B, fontSize: 10, color: C.lowScore, bold: true, margin: 0, valign: "middle" });
  });

  // Bottom row: other safety benchmarks
  const otherSafety = [
    { title: "PropensityBench", value: "10.50", note: "o3 (lower=better)", color: C.accent },
    { title: "Prof. Reasoning — Legal", value: "52.27", note: "Claude Opus 4.6 #1", color: C.anthropic },
    { title: "Prof. Reasoning — Finance", value: "53.28", note: "Claude Opus 4.6 #1", color: C.anthropic },
    { title: "Remote Labor Index", value: "4.17", note: "Claude Opus 4.6 (CoWo)", color: C.anthropic },
  ];

  otherSafety.forEach((item, i) => {
    const cx = 0.4 + i * 2.35;
    s.addShape(pres.shapes.RECTANGLE, { x: cx, y: 4.1, w: 2.15, h: 1.2, fill: { color: C.bgCard }, shadow: mkShadow() });
    s.addShape(pres.shapes.RECTANGLE, { x: cx, y: 4.1, w: 2.15, h: 0.06, fill: { color: item.color } });
    s.addText(item.title, { x: cx + 0.12, y: 4.22, w: 1.9, h: 0.25, fontFace: FONT_B, fontSize: 9, color: C.textSecondary, margin: 0 });
    s.addText(item.value, { x: cx + 0.12, y: 4.5, w: 1.9, h: 0.4, fontFace: FONT_H, fontSize: 22, color: item.color, bold: true, margin: 0 });
    s.addText(item.note, { x: cx + 0.12, y: 4.9, w: 1.9, h: 0.25, fontFace: FONT_B, fontSize: 8, color: C.textMuted, margin: 0 });
  });
}

// =====================================================================
// SLIDE 7: LAB COMPETITIVE LANDSCAPE (heatmap matrix)
// =====================================================================
{
  const s = pres.addSlide();
  s.background = { color: C.bgLight };

  s.addText("Competitive Landscape: No Single Lab Wins Everywhere", {
    x: 0.6, y: 0.3, w: 9, h: 0.6,
    fontFace: FONT_H, fontSize: 26, color: C.textPrimary, bold: true, margin: 0,
  });
  s.addText("Heatmap of #1-ranked lab/model per benchmark across all four domains", {
    x: 0.6, y: 0.85, w: 9, h: 0.3,
    fontFace: FONT_B, fontSize: 13, color: C.textSecondary, margin: 0,
  });

  // Matrix data: [benchmark, domain, winner lab, winner model, score]
  const matrix = [
    ["SWE Atlas – Test Writing", "Agentic", "OpenAI", "GPT-5.4-xHigh", "44.36"],
    ["SWE Atlas – Codebase QnA", "Agentic", "OpenAI", "GPT 5.4 xHigh", "40.80"],
    ["MCP Atlas (Tool Use)", "Agentic", "Muse Spark", "Muse Spark", "78.30"],
    ["SWE-Bench Pro (Public)", "Agentic", "OpenAI", "GPT-5.4-pro", "59.10"],
    ["SWE-Bench Pro (Private)", "Agentic", "Anthropic", "Claude Opus 4.6", "47.10"],
    ["Humanity's Last Exam", "Frontier", "OpenAI", "GPT-5.4-pro", "44.32"],
    ["EnigmaEval", "Frontier", "OpenAI", "GPT-5.4-pro", "23.82"],
    ["MultiChallenge", "Frontier", "Muse Spark", "Muse Spark", "75.52"],
    ["MultiNRC", "Frontier", "OpenAI", "GPT-5-pro", "65.20"],
    ["SciPredict", "Frontier", "Google", "Gemini-3-pro", "25.27"],
    ["AudioMultiChallenge (Text)", "Multimodal", "Google", "Gemini-3-pro", "54.65"],
    ["AudioMultiChallenge (Audio)", "Multimodal", "Google", "Gemini-3.1-flash", "36.06"],
    ["VISTA", "Multimodal", "Google", "Gemini 2.5 Pro", "54.65"],
    ["VisualToolBench", "Multimodal", "OpenAI", "GPT-5.4", "29.17"],
    ["MASK (Honesty)", "Safety", "Anthropic", "Claude Opus 4.6", "96.28"],
    ["Prof. Reasoning – Legal", "Safety", "Anthropic", "Claude Opus 4.6", "52.27"],
    ["Prof. Reasoning – Finance", "Safety", "Anthropic", "Claude Opus 4.6", "53.28"],
    ["Remote Labor Index", "Safety", "Anthropic", "Claude Opus 4.6", "4.17"],
  ];

  const labColor = (lab) => {
    if (lab === "OpenAI") return C.openai;
    if (lab === "Google") return C.google;
    if (lab === "Anthropic") return C.anthropic;
    if (lab === "Muse Spark") return C.museSpark;
    return C.textMuted;
  };

  const labBg = (lab) => {
    if (lab === "OpenAI") return "ECFDF5";
    if (lab === "Google") return "EFF6FF";
    if (lab === "Anthropic") return "F5F3FF";
    if (lab === "Muse Spark") return "FFFBEB";
    return "F1F5F9";
  };

  const hdrOpts = { fill: { color: C.bgDark }, color: C.textLight, bold: true, fontSize: 8, fontFace: FONT_B, align: "center", valign: "middle" };
  const hdrLeft = { ...hdrOpts, align: "left" };

  const rows = [
    [
      { text: "Benchmark", options: hdrLeft },
      { text: "Domain", options: hdrOpts },
      { text: "#1 Lab", options: hdrOpts },
      { text: "#1 Model", options: hdrOpts },
      { text: "Score", options: hdrOpts },
    ],
  ];

  matrix.forEach((row) => {
    const bg = labBg(row[2]);
    const lc = labColor(row[2]);
    rows.push([
      { text: row[0], options: { fontSize: 8, fontFace: FONT_B, color: C.textPrimary, align: "left", valign: "middle", fill: { color: bg } } },
      { text: row[1], options: { fontSize: 8, fontFace: FONT_B, color: C.textSecondary, align: "center", valign: "middle", fill: { color: bg } } },
      { text: row[2], options: { fontSize: 8, fontFace: FONT_B, color: lc, bold: true, align: "center", valign: "middle", fill: { color: bg } } },
      { text: row[3], options: { fontSize: 8, fontFace: FONT_B, color: C.textPrimary, align: "center", valign: "middle", fill: { color: bg } } },
      { text: row[4], options: { fontSize: 8, fontFace: FONT_B, color: lc, bold: true, align: "center", valign: "middle", fill: { color: bg } } },
    ]);
  });

  s.addTable(rows, {
    x: 0.3, y: 1.25, w: 9.4,
    colW: [2.5, 1.1, 1.2, 2.7, 0.8],
    border: { pt: 0.3, color: C.gridLine },
    rowH: [0.3, ...Array(matrix.length).fill(0.22)],
  });

  // Summary counters at bottom
  const counts = [
    { lab: "OpenAI", count: 7, color: C.openai },
    { lab: "Google", count: 4, color: C.google },
    { lab: "Anthropic", count: 5, color: C.anthropic },
    { lab: "Muse Spark", count: 2, color: C.museSpark },
  ];

  counts.forEach((c, i) => {
    const cx = 1.3 + i * 2.1;
    s.addShape(pres.shapes.RECTANGLE, { x: cx, y: 5.15, w: 1.8, h: 0.35, fill: { color: c.color }, transparency: 15 });
    s.addText(c.lab + ": " + c.count + " wins", {
      x: cx, y: 5.15, w: 1.8, h: 0.35,
      fontFace: FONT_B, fontSize: 10, color: C.textLight, bold: true, align: "center", valign: "middle", margin: 0,
    });
  });
}

// =====================================================================
// SLIDE 8: KEY TAKEAWAYS
// =====================================================================
{
  const s = pres.addSlide();
  s.background = { color: C.bgDark };

  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent } });

  s.addText("Key Takeaways", {
    x: 0.8, y: 0.3, w: 8.5, h: 0.55,
    fontFace: FONT_H, fontSize: 30, color: C.textLight, bold: true, margin: 0,
  });
  s.addText("No Single Model Wins Everything — Specialization Is the New Frontier", {
    x: 0.8, y: 0.85, w: 8.5, h: 0.4,
    fontFace: FONT_B, fontSize: 15, color: C.accent, italic: true, margin: 0,
  });

  const takeaways = [
    { icon: "1", color: C.openai, title: "GPT-5.4 leads agentic coding and frontier reasoning", desc: "Dominates SWE Atlas, SWE-Bench Pro (Public), HLE, and EnigmaEval — but does not lead multimodal or safety." },
    { icon: "2", color: C.google, title: "Gemini sweeps audio and vision-language", desc: "All top-3 positions on AudioMultiChallenge (Text Output) are Gemini variants. Leads VISTA vision-language." },
    { icon: "3", color: C.anthropic, title: "Claude leads safety, honesty, and professional reasoning", desc: "96%+ on MASK honesty. #1 on both Legal and Finance professional reasoning benchmarks." },
    { icon: "4", color: C.highlight, title: "Benchmarks remain far from saturation", desc: "HLE (44%), EnigmaEval (24%), SciPredict (25%) — substantial room for improvement across all labs." },
    { icon: "5", color: C.museSpark, title: "Muse Spark emerges as a strong new competitor", desc: "Top 3 on 6+ benchmarks including #1 on MultiChallenge (75.5%) and MCP Atlas tool use (78.3)." },
  ];

  takeaways.forEach((t, i) => {
    const yy = 1.55 + i * 0.78;

    // Number circle
    s.addShape(pres.shapes.OVAL, { x: 0.8, y: yy + 0.05, w: 0.38, h: 0.38, fill: { color: t.color } });
    s.addText(t.icon, {
      x: 0.8, y: yy + 0.05, w: 0.38, h: 0.38,
      fontFace: FONT_H, fontSize: 14, color: C.textLight, bold: true, align: "center", valign: "middle", margin: 0,
    });

    s.addText(t.title, {
      x: 1.4, y: yy, w: 8.0, h: 0.3,
      fontFace: FONT_H, fontSize: 14, color: C.textLight, bold: true, margin: 0,
    });
    s.addText(t.desc, {
      x: 1.4, y: yy + 0.32, w: 8.0, h: 0.35,
      fontFace: FONT_B, fontSize: 11, color: C.textMuted, margin: 0,
    });
  });

  // Footer
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.1, w: 10, h: 0.06, fill: { color: C.accent }, transparency: 40 });
  s.addText("Source: Scale SEAL Leaderboards  |  scale.com/leaderboard  |  All scores include confidence intervals", {
    x: 0.8, y: 5.2, w: 8.5, h: 0.3,
    fontFace: FONT_B, fontSize: 9, color: C.textMuted, align: "center", margin: 0,
  });
}

// =====================================================================
// SAVE
// =====================================================================
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Deck saved to /app/output/final_deck.pptx"))
  .catch((err) => console.error("Error:", err));

