const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Scale AI Analysis";
pres.title = "Scale SEAL Leaderboards: Frontier Model Performance Across 20+ Benchmarks";

// Color palette — dark analytical theme with lab-specific colors
const C = {
  bgDark: "0F172A",       // deep navy for title/conclusion
  bgLight: "F8FAFC",      // off-white for content slides
  bgCard: "FFFFFF",        // white cards
  accent: "6366F1",        // indigo accent
  textPrimary: "0F172A",
  textSecondary: "475569",
  textMuted: "94A3B8",
  textLight: "FFFFFF",
  // Lab colors
  openai: "10B981",        // emerald for OpenAI
  google: "3B82F6",        // blue for Google
  anthropic: "8B5CF6",     // violet for Anthropic
  museSpark: "F59E0B",     // amber for Muse Spark
  // Chart extras
  gridLine: "E2E8F0",
  cardBorder: "E2E8F0",
  barOpenAI: "10B981",
  barGoogle: "3B82F6",
  barAnthropic: "8B5CF6",
  barMuse: "F59E0B",
  highlight: "EF4444",     // red for low/critical
  highScore: "10B981",     // green for high scores
  lowScore: "EF4444",      // red for low scores
};

const FONT_H = "Trebuchet MS";
const FONT_B = "Calibri";

// Helper: fresh shadow
const mkShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.10 });

// =====================================================================
// SLIDE 1: TITLE
// =====================================================================
{
  const s = pres.addSlide();
  s.background = { color: C.bgDark };

  // Subtle decorative shapes
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent } });
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.8, w: 10, h: 0.06, fill: { color: C.accent }, transparency: 40 });

  s.addText("SCALE SEAL LEADERBOARDS", {
    x: 0.8, y: 1.0, w: 8.5, h: 0.7,
    fontFace: FONT_H, fontSize: 16, color: C.accent, charSpacing: 6, bold: true, margin: 0,
  });

  s.addText("Frontier Model Performance\nAcross 20+ Benchmarks", {
    x: 0.8, y: 1.7, w: 8.5, h: 1.8,
    fontFace: FONT_H, fontSize: 38, color: C.textLight, bold: true, lineSpacingMultiple: 1.1, margin: 0,
  });

  s.addText("A comparative analysis of 100+ AI models spanning agentic coding, reasoning,\nsafety, and multimodal capabilities — evaluated by Scale Labs", {
    x: 0.8, y: 3.6, w: 8.5, h: 0.9,
    fontFace: FONT_B, fontSize: 14, color: C.textMuted, lineSpacingMultiple: 1.3, margin: 0,
  });

  // Lab color legend at bottom
  const labs = [
    { name: "OpenAI", color: C.openai },
    { name: "Google", color: C.google },
    { name: "Anthropic", color: C.anthropic },
    { name: "Muse Spark", color: C.museSpark },
  ];
  labs.forEach((lab, i) => {
    const startX = 0.8 + i * 2.2;
    s.addShape(pres.shapes.RECTANGLE, { x: startX, y: 4.95, w: 0.25, h: 0.25, fill: { color: lab.color }, rectRadius: 0.02 });
    s.addText(lab.name, { x: startX + 0.35, y: 4.93, w: 1.6, h: 0.3, fontFace: FONT_B, fontSize: 11, color: C.textMuted, margin: 0 });
  });
}

// =====================================================================
// SLIDE 2: BENCHMARK LANDSCAPE OVERVIEW
// =====================================================================
{
  const s = pres.addSlide();
  s.background = { color: C.bgLight };

  s.addText("20+ Benchmarks Spanning Four Capability Domains", {
    x: 0.6, y: 0.3, w: 9, h: 0.6,
    fontFace: FONT_H, fontSize: 28, color: C.textPrimary, bold: true, margin: 0,
  });
  s.addText("Evaluating 100+ models from OpenAI, Google, Anthropic, Meta, and open-source contributors", {
    x: 0.6, y: 0.9, w: 9, h: 0.4,
    fontFace: FONT_B, fontSize: 13, color: C.textSecondary, margin: 0,
  });

  const domains = [
    {
      title: "AGENTIC", subtitle: "Coding & Tool Use", color: C.openai,
      benchmarks: ["SWE Atlas (Test Writing)", "SWE Atlas (Codebase QnA)", "MCP Atlas (Tool Use)", "SWE-Bench Pro (Pub/Priv)"],
    },
    {
      title: "FRONTIER", subtitle: "Reasoning & Knowledge", color: C.museSpark,
      benchmarks: ["Humanity's Last Exam", "EnigmaEval", "MultiChallenge", "MultiNRC", "SciPredict"],
    },
    {
      title: "SAFETY", subtitle: "Alignment & Honesty", color: C.anthropic,
      benchmarks: ["MASK (Honesty)", "PropensityBench", "Fortress (Nat'l Security)", "Professional Reasoning"],
    },
    {
      title: "MULTIMODAL", subtitle: "Audio & Vision", color: C.google,
      benchmarks: ["AudioMultiChallenge", "VISTA (Vision-Language)", "VisualToolBench"],
    },
  ];

  const cardW = 2.1;
  const gap = 0.2;
  const startX = (10 - (4 * cardW + 3 * gap)) / 2;

  domains.forEach((d, i) => {
    const cx = startX + i * (cardW + gap);
    const cy = 1.65;
    const ch = 3.5;

    // Card background
    s.addShape(pres.shapes.RECTANGLE, { x: cx, y: cy, w: cardW, h: ch, fill: { color: C.bgCard }, shadow: mkShadow() });
    // Top color bar
    s.addShape(pres.shapes.RECTANGLE, { x: cx, y: cy, w: cardW, h: 0.08, fill: { color: d.color } });

    // Domain label
    s.addText(d.title, {
      x: cx + 0.15, y: cy + 0.25, w: cardW - 0.3, h: 0.35,
      fontFace: FONT_H, fontSize: 14, color: d.color, bold: true, charSpacing: 3, margin: 0,
    });
    s.addText(d.subtitle, {
      x: cx + 0.15, y: cy + 0.6, w: cardW - 0.3, h: 0.3,
      fontFace: FONT_B, fontSize: 11, color: C.textSecondary, margin: 0,
    });

    // Separator
